H,W=30,24
out=[[4]*W for _ in range(H)]
# First panel: rows 13..20, fill 7 with side rails 3
for r in range(13,21):
    out[r]=[3]+[7]*22+[3]
# Stamp first top object, bottom-aligned: 7 -> rail color 3, 3 -> panel fill 7
obj1=[[7,7,7,7,7,7,7]]+[[7,3,3,7,3,3,7] for _ in range(3)]+[[7,7,7,7,7,7,7]]
for i,row in enumerate(obj1):
    for j,v in enumerate(row):
        out[16+i][9+j]=3 if v==7 else 7
# Second panel rows 22..27, fill 3 with side rails 9
for r in range(22,28):
    out[r]=[9]+[3]*22+[9]
# Stamp second top object, bottom-aligned: 7 -> rail color 9, 3 -> panel fill 3
obj2=[[7]*4,[7,3,3,7],[7,3,3,7],[7]*4]
for i,row in enumerate(obj2):
    for j,v in enumerate(row):
        out[24+i][19+j]=9 if v==7 else 3
print('\n'.join(' '.join(map(str,row)) for row in out))
print([len(r) for r in out])
